B.cg0={"*\u0645\u0644\u062e\u0635 \u0623\u0633\u0628\u0648\u0639\u064a - {p}*\n{a} \u0625\u0644\u0649 {b}\n\n{s}":0,[u.u]:1,[u.mK]:2,"\u0623\u0636\u0641":3,"\u0627\u0644\u0645\u0647\u0646\u0629: {t}":4,"\u0623\u0636\u0641 \u0627\u0644\u0628\u0627\u0642\u064a \u0643\u0644\u0647\u0627":5,"\u0627\u062a\u062d\u0641\u0638\u062a \u0641\u064a \u064a\u0648\u0645\u064a\u0629 {d}":6,"\u0627\u062a\u0636\u0627\u0641\u062a {n} \u0645\u0644\u0627\u062d\u0638\u0629":7,"\u0627\u062a\u0642\u0631\u0627 {n} \u0645\u0644\u0641 PDF.":8,"\u0627\u062d\u0641\u0638 \u0641\u064a \u0627\u0644\u064a\u0648\u0645\u064a\u0629":9,"\u0627\u062d\u0643\u064a \u0639\u0646 \u0634\u063a\u0644 \u0627\u0644\u0646\u0647\u0627\u0631\u062f\u0647 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)":10,"\u0627\u062e\u062a\u0627\u0631":11,"\u0627\u0633\u0623\u0644":12,"\u0627\u0633\u0623\u0644 \u0627\u0644\u0645\u0633\u062a\u0646\u062f\u0627\u062a":13,[u.nh]:14,"\u0627\u0642\u062a\u0631\u0627\u062d \u0627\u0633\u062a\u0641\u0633\u0627\u0631\u0627\u062a":15,"\u0627\u0642\u062a\u0631\u0627\u062d \u0627\u0633\u062a\u0641\u0633\u0627\u0631\u0627\u062a (RFI)":16,"\u0627\u0642\u062a\u0631\u062d \u0627\u0633\u062a\u0641\u0633\u0627\u0631\u0627\u062a":17,"\u0627\u0642\u0631\u0623 \u0645\u0644\u0641\u0627\u062a PDF \u0627\u0644\u0645\u0637\u0627\u0628\u0642\u0629 (\u0644\u062d\u062f 3)":18,"\u0627\u0643\u062a\u0628 \u0633\u0624\u0627\u0644\u0643 \u0627\u0644\u0623\u0648\u0644.":19,"\u0627\u0643\u062a\u0628 \u0645\u0644\u062e\u0635 \u0622\u062e\u0631 7 \u0623\u064a\u0627\u0645":20,"\u0627\u0643\u062a\u0628\u0647 \u062a\u0627\u0646\u064a":21,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629":22,"\u0627\u0644\u062e\u062f\u0645\u0629 \u0645\u0634\u063a\u0648\u0644\u0629 \u062f\u0644\u0648\u0642\u062a\u064a. \u062c\u0631\u0651\u0628 \u0628\u0639\u062f \u0634\u0648\u064a\u0629.":23,"\u0627\u0644\u0645\u0631\u0627\u062c\u0639":24,"\u0627\u0644\u0645\u0633\u0627\u0639\u062f \u0627\u0644\u0630\u0643\u064a \u0645\u062d\u062a\u0627\u062c \u0646\u062a \u0648\u0633\u064a\u0631\u0641\u0631 \u0627\u0644\u0645\u0634\u0631\u0648\u0639. \u0627\u0644\u0646\u0633\u062e\u0629 \u0627\u0644\u062a\u062c\u0631\u064a\u0628\u064a\u0629 \u0623\u0648 \u0645\u0646 \u063a\u064a\u0631 \u0627\u062a\u0635\u0627\u0644 \u0645\u0634 \u0628\u062a\u062f\u0639\u0645\u0647\u060c \u0648\u0628\u0627\u0642\u064a \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0634\u063a\u0627\u0644 \u0639\u0627\u062f\u064a.":25,[u.mf]:26,[u.bp]:27,"\u0627\u0644\u0645\u0633\u0627\u0639\u062f \u0631\u0641\u0636 \u0627\u0644\u0637\u0644\u0628 \u062f\u0647.":28,[u.kC]:29,[u.jP]:30,[u.jp]:31,"\u0627\u0644\u0645\u0633\u0627\u0639\u062f \u0645\u0627\u0643\u062a\u0628\u0634 \u0645\u0644\u062e\u0635. \u062c\u0631\u0651\u0628 \u062a\u0627\u0646\u064a.":32,"\u0627\u0644\u0645\u0644\u062e\u0635 \u0627\u0644\u0623\u0633\u0628\u0648\u0639\u064a":33,"\u062a\u0636\u064a\u0641 {n} \u0645\u0644\u0627\u062d\u0638\u0629 \u0644\u0644\u0645\u0634\u0631\u0648\u0639\u061f":34,"\u062c\u0647\u0651\u0632 \u0627\u0644\u0645\u0633\u0648\u062f\u0629":35,"\u062c\u0647\u0651\u0632 \u0645\u0633\u0648\u062f\u0629 \u062a\u0627\u0646\u064a\u0629":36,"\u062d\u0635\u0644\u062a \u0645\u0634\u0643\u0644\u0629 \u063a\u064a\u0631 \u0645\u062a\u0648\u0642\u0639\u0629: {e}":37,"\u062d\u0635\u0644\u062a \u0645\u0634\u0643\u0644\u0629 \u0641\u064a \u0627\u0644\u0645\u0633\u0627\u0639\u062f{c}. \u062c\u0631\u0651\u0628 \u062a\u0627\u0646\u064a.":38,[u.nY]:39,"\u062f\u0627\u0644\u0629 \u0627\u0644\u0645\u0633\u0627\u0639\u062f \u0644\u0633\u0647 \u0645\u0634 \u0645\u062a\u0631\u0643\u0628\u0629 \u0639\u0644\u0649 \u0627\u0644\u0633\u064a\u0631\u0641\u0631.":40,"\u0631\u0627\u062c\u0639 \u0648\u0623\u0636\u0641":41,"\u0631\u0627\u062c\u0639 \u0648\u0639\u062f\u0651\u0644 \u0642\u0628\u0644 \u0627\u0644\u062d\u0641\u0638":42,"\u0631\u062f \u063a\u064a\u0631 \u0645\u062a\u0648\u0642\u0639 \u0645\u0646 \u0627\u0644\u0633\u064a\u0631\u0641\u0631.":43,"\u0633\u0624\u0627\u0644\u0643":44,"\u0635\u0648\u0651\u0631":45,[u.p0]:46,[u.mo]:47,"\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0646\u0647\u0627\u0631\u062f\u0647: {u} \u0645\u0646 {l}":48,[u.ek]:49,"\u0644\u0627\u0632\u0645 \u062a\u0633\u062c\u0644 \u062f\u062e\u0648\u0644\u0643 \u0627\u0644\u0623\u0648\u0644.":50,[u.fn]:51,[u.oR]:52,"\u0645\u0633\u0648\u062f\u0629 \u0627\u0644\u064a\u0648\u0645\u064a\u0629":53,"\u0645\u0634 \u0645\u0633\u0645\u0648\u062d\u0644\u0643 \u062a\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0645\u0633\u0627\u0639\u062f \u0641\u064a \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u062f\u0647.":54,"\u0645\u0634 \u0645\u0633\u0645\u0648\u062d\u0644\u0643 \u062a\u0639\u062f\u0651\u0644 \u0627\u0644\u064a\u0648\u0645\u064a\u0629 \u062f\u064a.":55,"\u0645\u0634\u0627\u0631\u0643\u0629 (\u0648\u0627\u062a\u0633\u0627\u0628)":56,[u.k_]:57,"\u0645\u0641\u064a\u0634 \u0627\u0633\u062a\u0641\u0633\u0627\u0631\u0627\u062a \u0645\u0642\u062a\u0631\u062d\u0629 \u0627\u0644\u0645\u0631\u0629 \u062f\u064a.":58,[u.ik]:59,"\u0645\u0644\u0627\u062d\u0638\u0627\u062a \u0645\u0642\u062a\u0631\u062d\u0629 ({n})":60,"\u0645\u0644\u0627\u062d\u0638\u0627\u062a \u0645\u0646 \u0641\u064a\u062f\u064a\u0648":61,[u.ed]:62,[u.h6]:63}
B.bZN=s(["*Weekly summary - {p}*\n{a} to {b}\n\n{s}","*R\xe9sum\xe9 hebdomadaire - {p}*\n{a} au {b}\n\n{s}"],t.s)
